private val Ink=Color(0xFF080D18);private val Panel=Color(0xFF111B2D);private val Panel2=Color(0xFF18263C);private val Line=Color(0xFF293A54);private val White=Color(0xFFF2F6FF);private val Muted=Color(0xFF96A7C1);private val Blue=Color(0xFF4D8DFF);private val Cyan=Color(0xFF60D9FF);private val Red=Color(0xFFFF7185)
