@Composable private fun PrivateSpaceRoot(){
 val c=LocalContext.current;val repo=remember{VaultRepository(c.applicationContext)};val scope=rememberCoroutineScope()
 var unlocked by remember{mutableStateOf(false)};var setup by remember{mutableStateOf(!PasswordManager.configured(c))};var pass by remember{mutableStateOf("")};var confirm by remember{mutableStateOf("")};var error by remember{mutableStateOf("")};var busy by remember{mutableStateOf(false)};var lockUntil by remember{mutableLongStateOf(PasswordManager.lockedUntil(c))}
 var topics by remember{mutableStateOf(emptyList<TopicSummary>())};var selected by remember{mutableStateOf<String?>(null)};var create by remember{mutableStateOf(false)};var name by remember{mutableStateOf("")};var change by remember{mutableStateOf(false)};var removeTopic by remember{mutableStateOf<VaultTopic?>(null)};var removeFile by remember{mutableStateOf<VaultFile?>(null)};var addTo by remember{mutableStateOf<String?>(null)};var exportOneId by remember{mutableStateOf<String?>(null)};var exportTopicId by remember{mutableStateOf<String?>(null)};var exportAll by remember{mutableStateOf(false)};var shareFileId by remember{mutableStateOf<String?>(null)};var shareTopicId by remember{mutableStateOf<String?>(null)}
 fun refresh(){topics=repo.summaries()}
 val pick=rememberLauncherForActivityResult(ActivityResultContracts.OpenMultipleDocuments()){uris->val id=addTo?:return@rememberLauncherForActivityResult;addTo=null;scope.launch{busy=true;val errors=withContext(Dispatchers.IO){uris.mapNotNull{u->runCatching{repo.addFile(id,u)}.exceptionOrNull()?.message}};busy=false;refresh();if(errors.isNotEmpty())Toast.makeText(c,errors.joinToString("\n"),Toast.LENGTH_LONG).show()}}
 val saveFile=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/octet-stream")){uri->val id=exportOneId?:return@rememberLauncherForActivityResult;exportOneId=null;if(uri!=null)scope.launch{busy=true;val result=withContext(Dispatchers.IO){runCatching{repo.export(id,DocumentFile.fromSingleUri(c,uri)?:error("Invalid export target."))}};busy=false;result.onSuccess{Toast.makeText(c,"Exported. This copy is outside the encrypted vault.",Toast.LENGTH_LONG).show()}.onFailure{Toast.makeText(c,it.message,Toast.LENGTH_LONG).show()}}}
 val chooseFolder=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocumentTree()){uri->if(uri!=null)scope.launch{busy=true;val tid=exportTopicId;val all=exportAll;exportTopicId=null;exportAll=false;val result=withContext(Dispatchers.IO){runCatching{val root=DocumentFile.fromTreeUri(c,uri)?:error("Invalid folder.");val selectedTopics=if(all)repo.topics() else listOf(repo.topics().first{it.id==tid});selectedTopics.forEach{topic->val folder=root.createDirectory(topic.name)?:error("Could not create ${topic.name}");repo.files().filter{it.topicId==topic.id}.forEach{file->val target=folder.createFile(file.mimeType,file.displayName)?:error("Could not create ${file.displayName}");repo.export(file.id,target)}}}};busy=false;result.onSuccess{Toast.makeText(c,"Export complete. Exported files are not protected by the vault password.",Toast.LENGTH_LONG).show()}.onFailure{Toast.makeText(c,it.message,Toast.LENGTH_LONG).show()}}}
 LaunchedEffect(unlocked){if(unlocked)refresh()};BackHandler(enabled=!unlocked){}
 if(!unlocked){AuthScreen(setup,pass,confirm,error,busy,lockUntil,{pass=it},{confirm=it}){if(busy||lockUntil>System.currentTimeMillis())return@AuthScreen;busy=true;val chars=pass.toCharArray();val confirmation=confirm;scope.launch{val result=withContext(Dispatchers.IO){runCatching{if(setup){require(chars.size>=8){"Use at least 8 characters."};require(String(chars)==confirmation){"Passwords do not match."};PasswordManager.set(c,chars);true}else PasswordManager.verify(c,chars)}};busy=false;result.fold({valid->if(valid){PasswordManager.clearFailures(c);setup=false;unlocked=true;pass="";confirm="";error=""}else{lockUntil=PasswordManager.fail(c);error="Incorrect password.";pass=""}},{error=it.message?:"Authentication failed."})}};return}
 Scaffold(containerColor=Ink,topBar={Row(Modifier.fillMaxWidth().background(Ink).padding(horizontal=18.dp,vertical=14.dp),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Lock,null,tint=Cyan,modifier=Modifier.size(30.dp));Spacer(Modifier.width(10.dp));Column(Modifier.weight(1f)){Text("PRIVATE SPACE",fontWeight=FontWeight.Black,color=White,letterSpacing=1.2.sp);Text("YOUR PERSONAL DOCUMENT VAULT",fontSize=9.sp,color=Muted)};IconButton(onClick={change=true}){Icon(Icons.Default.Key,"Change password",tint=Muted)};IconButton(onClick={unlocked=false;pass=""}){Icon(Icons.Default.Lock,"Lock vault",tint=Muted)}}},floatingActionButton={FloatingActionButton(onClick={create=true},containerColor=Blue){Icon(Icons.Default.Add,"Create topic",tint=Color.White)}}){padding->LazyColumn(Modifier.fillMaxSize().padding(padding),contentPadding=PaddingValues(16.dp),verticalArrangement=Arrangement.spacedBy(12.dp)){item{Card(colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(20.dp)){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){Text("YOUR VAULT",color=Cyan,fontWeight=FontWeight.Bold,fontSize=10.sp);Text("${topics.size} topics · ${topics.sumOf{it.fileCount}} files",color=White,fontSize=21.sp,fontWeight=FontWeight.Bold);OutlinedButton(onClick={exportAll=true;chooseFolder.launch(null)}){Icon(Icons.Default.FolderZip,null);Spacer(Modifier.width(6.dp));Text("Export all topics")}}}};if(topics.isEmpty())item{Text("Create a topic to start adding your documents and photos.",color=Muted)};items(topics,key={it.topic.id}){s->TopicCard(s,{selected=s.topic.id},{exportTopicId=s.topic.id;chooseFolder.launch(null)},{removeTopic=s.topic})};item{Spacer(Modifier.height(70.dp))}}}
 selected?.let{id->TopicDialog(repo,id,{addTo=id;pick.launch(arrayOf("*/*"))},{f->scope.launch{busy=true;val file=withContext(Dispatchers.IO){runCatching{repo.decrypt(f.id)}};busy=false;file.onSuccess{clear->val uri=FileProvider.getUriForFile(c,"com.privatespace.android.fileprovider",clear);val view=Intent(Intent.ACTION_VIEW).setDataAndType(uri,f.mimeType).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);runCatching{c.startActivity(view)}.onFailure{clear.delete();Toast.makeText(c,"No compatible app found.",Toast.LENGTH_LONG).show()}}.onFailure{Toast.makeText(c,it.message,Toast.LENGTH_LONG).show()}}},{shareFileId=it.id},{exportOneId=it.id;saveFile.launch(it.displayName)},{removeFile=it},{shareTopicId=id})}
 if(create)AlertDialog(onDismissRequest={create=false},title={Text("Create topic")},text={OutlinedTextField(name,{name=it},label={Text("Topic name")},singleLine=true)},confirmButton={TextButton(onClick={runCatching{repo.createTopic(name)}.onSuccess{name="";create=false;refresh()}.onFailure{Toast.makeText(c,it.message,Toast.LENGTH_LONG).show()}}){Text("Create")}},dismissButton={TextButton(onClick={create=false}){Text("Cancel")}})
 removeTopic?.let{t->ConfirmDialog("Delete topic and files?","This permanently removes the topic and all encrypted copies.",{removeTopic=null},{repo.deleteTopic(t.id);removeTopic=null;selected=null;refresh()})};removeFile?.let{f->ConfirmDialog("Delete file?","This permanently removes its encrypted copy.",{removeFile=null},{repo.deleteFile(f.id);removeFile=null;refresh()})}
 if(change)ChangePasswordDialog({change=false}){old,new->scope.launch{val result=withContext(Dispatchers.IO){runCatching{require(PasswordManager.verify(c,old.toCharArray())){"Current password is incorrect."};PasswordManager.set(c,new.toCharArray())}};result.onSuccess{change=false;Toast.makeText(c,"Password changed.",Toast.LENGTH_SHORT).show()}.onFailure{Toast.makeText(c,it.message,Toast.LENGTH_LONG).show()}}}
 shareFileId?.let{id->LaunchedEffect(id){withContext(Dispatchers.IO){runCatching{repo.share(id)}}.onSuccess{(uri,mime)->c.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).setType(mime).putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share file"))}.onFailure{Toast.makeText(c,it.message,Toast.LENGTH_LONG).show()};shareFileId=null}}
 shareTopicId?.let{id->LaunchedEffect(id){val fs=repo.files().filter{it.topicId==id};val result=withContext(Dispatchers.IO){runCatching{fs.map{f->val clear=repo.decrypt(f.id);val stable=File(c.cacheDir,"outgoing/topic-$id-${f.id}-${f.displayName}");stable.parentFile?.mkdirs();clear.copyTo(stable,true);clear.delete();FileProvider.getUriForFile(c,"com.privatespace.android.fileprovider",stable)}}};result.onSuccess{uris->if(uris.isNotEmpty())c.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND_MULTIPLE).setType("*/*").putParcelableArrayListExtra(Intent.EXTRA_STREAM,ArrayList(uris)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION),"Share topic"))else Toast.makeText(c,"No files in this topic.",Toast.LENGTH_SHORT).show()}.onFailure{Toast.makeText(c,it.message,Toast.LENGTH_LONG).show()};shareTopicId=null}}
 if(busy)LinearProgressIndicator(Modifier.fillMaxWidth(),color=Cyan)
}
@Composable private fun AuthScreen(setup:Boolean,password:String,confirm:String,error:String,busy:Boolean,lockUntil:Long,onPassword:(String)->Unit,onConfirm:(String)->Unit,onSubmit:()->Unit){Column(Modifier.fillMaxSize().background(Ink).padding(26.dp),verticalArrangement=Arrangement.Center,horizontalAlignment=Alignment.CenterHorizontally){Icon(Icons.Default.Lock,null,tint=Cyan,modifier=Modifier.size(54.dp));Spacer(Modifier.height(16.dp));Text("PRIVATE SPACE",fontSize=25.sp,fontWeight=FontWeight.Black,color=White,letterSpacing=2.sp);Text(if(setup)"Set up a password to begin" else "Unlock your personal vault",color=Muted);Spacer(Modifier.height(20.dp));OutlinedTextField(password,onPassword,modifier=Modifier.fillMaxWidth(),label={Text(if(setup)"Create password" else "Password")},singleLine=true,visualTransformation=PasswordVisualTransformation(),keyboardOptions=KeyboardOptions(keyboardType=KeyboardType.Password));if(setup)OutlinedTextField(confirm,onConfirm,modifier=Modifier.fillMaxWidth(),label={Text("Confirm password")},singleLine=true,visualTransformation=PasswordVisualTransformation());if(error.isNotBlank())Text(error,color=Red);if(lockUntil>System.currentTimeMillis())Text("Too many attempts. Try again later.",color=Red);Spacer(Modifier.height(14.dp));Button(onClick=onSubmit,enabled=!busy&&password.isNotEmpty()&&(!setup||confirm.isNotEmpty())&&lockUntil<=System.currentTimeMillis(),modifier=Modifier.fillMaxWidth().height(52.dp)){Text(if(busy)"Please wait…" else if(setup)"Create secure vault" else "Unlock")};Text("Your files are encrypted on this device.",color=Muted,fontSize=11.sp,modifier=Modifier.padding(top=14.dp))}}
@Composable private fun TopicCard(s:TopicSummary,onOpen:()->Unit,onExport:()->Unit,onDelete:()->Unit){Card(Modifier.fillMaxWidth().clickable(onClick=onOpen),colors=CardDefaults.cardColors(containerColor=Panel),shape=RoundedCornerShape(18.dp)){Column(Modifier.padding(15.dp)){Row(verticalAlignment=Alignment.CenterVertically){Icon(Icons.Default.Folder,null,tint=Cyan);Spacer(Modifier.width(8.dp));Text(s.topic.name,color=White,fontWeight=FontWeight.Bold,modifier=Modifier.weight(1f),maxLines=1,overflow=TextOverflow.Ellipsis);IconButton(onClick=onExport){Icon(Icons.Default.FileDownload,"Export topic",tint=Muted)};IconButton(onClick=onDelete){Icon(Icons.Default.DeleteOutline,"Delete topic",tint=Red)}};Text("${s.fileCount} files · ${formatBytes(s.totalBytes)}",color=Muted,fontSize=11.sp);Text("Created ${formatDate(s.topic.createdAt)} · Updated ${formatDate(s.topic.updatedAt)}",color=Muted,fontSize=10.sp)}}}
@Composable private fun TopicDialog(repo:VaultRepository,id:String,onAdd:()->Unit,onOpen:(VaultFile)->Unit,onShare:(VaultFile)->Unit,onExport:(VaultFile)->Unit,onDelete:(VaultFile)->Unit,onShareTopic:()->Unit){val t=repo.topics().firstOrNull{it.id==id}?:return;val fs=repo.files().filter{it.topicId==id};AlertDialog(onDismissRequest={},title={Column{Text(t.name);Text("${fs.size} files · Updated ${formatDate(t.updatedAt)}",color=Muted,fontSize=10.sp)}},text={Column(Modifier.heightIn(max=430.dp)){Button(onClick=onAdd,modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.Add,null);Text("Add documents / photos")};OutlinedButton(onClick=onShareTopic,modifier=Modifier.fillMaxWidth()){Icon(Icons.Default.Share,null);Text("Share entire topic")};LazyColumn{items(fs,key={it.id}){f->Row(Modifier.fillMaxWidth().padding(vertical=5.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(f.mimeType.startsWith("image/"))Icons.Default.Image else Icons.Default.Description,null,tint=Cyan);Spacer(Modifier.width(5.dp));Column(Modifier.weight(1f)){Text(f.displayName,color=White,fontSize=11.sp,maxLines=1,overflow=TextOverflow.Ellipsis);Text(formatBytes(f.sizeBytes),color=Muted,fontSize=9.sp)};IconButton(onClick={onOpen(f)}){Icon(Icons.Default.OpenInNew,"Open")};IconButton(onClick={onShare(f)}){Icon(Icons.Default.Share,"Share")};IconButton(onClick={onExport(f)}){Icon(Icons.Default.FileDownload,"Export")};IconButton(onClick={onDelete(f)}){Icon(Icons.Default.DeleteOutline,"Delete",tint=Red)}}}}}},confirmButton={TextButton(onClick={}){Text("Done")}})}
@Composable private fun ChangePasswordDialog(onDismiss:()->Unit,onChange:(String,String)->Unit){var old by remember{mutableStateOf("")};var new by remember{mutableStateOf("")};var confirm by remember{mutableStateOf("")};AlertDialog(onDismissRequest=onDismiss,title={Text("Change password")},text={Column{OutlinedTextField(old,{old=it},label={Text("Current password")},visualTransformation=PasswordVisualTransformation());OutlinedTextField(new,{new=it},label={Text("New password")},visualTransformation=PasswordVisualTransformation());OutlinedTextField(confirm,{confirm=it},label={Text("Confirm password")},visualTransformation=PasswordVisualTransformation())}},confirmButton={TextButton(enabled=old.isNotEmpty()&&new.length>=8&&new==confirm,onClick={onChange(old,new)}){Text("Change")}},dismissButton={TextButton(onClick=onDismiss){Text("Cancel")}})}
@Composable private fun ConfirmDialog(title:String,message:String,onCancel:()->Unit,onConfirm:()->Unit){AlertDialog(onDismissRequest=onCancel,title={Text(title)},text={Text(message)},confirmButton={TextButton(onClick=onConfirm){Text("Delete",color=Red)}},dismissButton={TextButton(onClick=onCancel){Text("Cancel")}})}
private fun formatDate(t:Long)=DateFormat.getDateTimeInstance(DateFormat.MEDIUM,DateFormat.SHORT).format(Date(t))
private fun formatBytes(v:Long):String=when{v<1024->"$v B";v<1048576->String.format("%.1f KB",v/1024.0);v<1073741824->String.format("%.1f MB",v/1048576.0);else->String.format("%.2f GB",v/1073741824.0)}
